"""Original vector core: all graphics are generated by QPainter, no images."""
from dataclasses import dataclass
import math
import time
from PyQt6.QtCore import QPointF, QRectF, Qt, QTimer, pyqtSignal
from PyQt6.QtGui import QColor, QFont, QPainter, QPen, QPolygonF, QRadialGradient
from PyQt6.QtWidgets import QWidget

@dataclass
class Burst:
    point: QPointF
    text: str
    born: float

class CoreWidget(QWidget):
    activated = pyqtSignal(QPointF)

    def __init__(self, parent: QWidget | None = None):
        super().__init__(parent)
        self.setMinimumSize(300, 360)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAccessibleName("Энергетическое ядро")
        self.setAccessibleDescription("Нажмите мышью, пробел или Enter для добычи энергии")
        self.setToolTip("Нажмите на ядро • Пробел / Enter при фокусе")
        self.reduced_motion = False
        self.bursts: list[Burst] = []
        self.last_pulse = 0.0
        self.started = time.monotonic()
        self.timer = QTimer(self)
        self.timer.setInterval(33)
        self.timer.timeout.connect(self.animate)

    def geometry_values(self) -> tuple[QPointF, float]:
        return QPointF(self.width() / 2, self.height() / 2 - 16), min(
            self.width() * .28, (self.height() - 90) * .36, 135)

    def showEvent(self, event):
        self.timer.start()
        super().showEvent(event)

    def hideEvent(self, event):
        self.timer.stop()
        super().hideEvent(event)

    def set_reduced_motion(self, value: bool) -> None:
        self.reduced_motion = value
        self.timer.setInterval(80 if value else 33)
        self.update()

    def animate(self) -> None:
        now = time.monotonic()
        self.bursts = [b for b in self.bursts if now - b.born < .9]
        self.update()

    def burst(self, point: QPointF, text: str) -> None:
        self.last_pulse = time.monotonic()
        self.bursts.append(Burst(point, text, self.last_pulse))
        self.bursts = self.bursts[-4:]
        self.update()

    def mousePressEvent(self, event):
        center, radius = self.geometry_values()
        if event.button() == Qt.MouseButton.LeftButton:
            point = event.position()
            if math.hypot(point.x() - center.x(), point.y() - center.y()) <= radius * 1.2:
                self.setFocus(Qt.FocusReason.MouseFocusReason)
                self.activated.emit(point)
                event.accept()
                return
        super().mousePressEvent(event)

    def keyPressEvent(self, event):
        if event.key() in (Qt.Key.Key_Space, Qt.Key.Key_Return, Qt.Key.Key_Enter):
            if not event.isAutoRepeat():
                self.activated.emit(self.geometry_values()[0])
            event.accept()
            return
        super().keyPressEvent(event)

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        center, r = self.geometry_values()
        now = time.monotonic()
        t = 0 if self.reduced_motion else now - self.started
        pulse_age = now - self.last_pulse
        kick = max(0.0, 1 - pulse_age / .32)
        breathing = 1 + (.018 * math.sin(t * 2) if not self.reduced_motion else 0)
        r *= breathing
        # Sparse technical field: subordinate to the core, never behind text.
        p.setPen(QPen(QColor("#11232e"), 1))
        for x in range(24, self.width(), 40):
            for y in range(34, self.height() - 64, 40):
                p.drawPoint(QPointF(x, y))
        p.setPen(QColor("#7895a5"))
        p.setFont(QFont("Segoe UI", 9))
        p.drawText(QRectF(0, 5, self.width(), 22), Qt.AlignmentFlag.AlignCenter,
                   "CORE / 01     •     ONLINE")
        gradient = QRadialGradient(center, r * 1.65)
        gradient.setColorAt(0, QColor(35, 219, 231, int(75 + kick * 55)))
        gradient.setColorAt(.55, QColor(17, 128, 162, 35))
        gradient.setColorAt(1, QColor(8, 16, 28, 0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(gradient)
        p.drawEllipse(center, r * 1.65, r * 1.65)
        p.setBrush(Qt.BrushStyle.NoBrush)
        # Concentric broken orbital arcs, deliberately limited to three rings.
        for i, color in enumerate(("#204654", "#49e6e6", "#a48bff")):
            orbit = r * (1.12 + i * .14)
            p.setPen(QPen(QColor(color), 1.4 if i != 1 else 2.2))
            rect = QRectF(center.x()-orbit, center.y()-orbit, orbit*2, orbit*2)
            rotation = (t * (10 if i % 2 == 0 else -14) + i * 50) % 360
            for section in range(3):
                p.drawArc(rect, int((rotation + section * 120) * 16), 74 * 16)
        # Six-sided containment chamber.
        polygon = QPolygonF([QPointF(center.x() + r * math.cos(math.radians(a)),
                                    center.y() + r * math.sin(math.radians(a)))
                             for a in range(-90, 270, 60)])
        p.setBrush(QColor("#0a1d2b"))
        p.setPen(QPen(QColor("#38becd"), 2))
        p.drawPolygon(polygon)
        inset = QPolygonF([center + (point-center) * .88 for point in polygon])
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor("#1a4654"), 1))
        p.drawPolygon(inset)
        # Compact energy lens.
        lens = r * (.49 + (.035 * kick if not self.reduced_motion else 0))
        g = QRadialGradient(center, lens)
        g.setColorAt(0, QColor("#edffff"))
        g.setColorAt(.2, QColor("#8ffff6"))
        g.setColorAt(.5, QColor("#22cad6"))
        g.setColorAt(1, QColor(17, 94, 126, 15))
        p.setBrush(g)
        p.setPen(Qt.PenStyle.NoPen)
        p.drawEllipse(center, lens, lens)
        p.setPen(QPen(QColor("#b2ffff"), 2))
        p.drawLine(center + QPointF(-r*.18, 0), center + QPointF(r*.18, 0))
        p.drawLine(center + QPointF(0, -r*.18), center + QPointF(0, r*.18))
        if self.hasFocus():
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor("#e2e8ff"), 1, Qt.PenStyle.DashLine))
            p.drawEllipse(center, r*1.03, r*1.03)
        if 0 <= pulse_age < .5 and not self.reduced_motion:
            wave_r = r * min(1.4, .7 + pulse_age * 2)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(95, 255, 235, int(150 * (1-pulse_age/.5))), 2))
            p.drawEllipse(center, wave_r, wave_r)
        p.setFont(QFont("Segoe UI", 10))
        p.setPen(QColor("#d2e5ec"))
        p.drawText(QRectF(0, self.height()-54, self.width(), 24),
                   Qt.AlignmentFlag.AlignCenter, "НАЖМИТЕ НА ЯДРО")
        p.setFont(QFont("Segoe UI", 9))
        p.setPen(QColor("#8da5b7"))
        p.drawText(QRectF(0, self.height()-29, self.width(), 20),
                   Qt.AlignmentFlag.AlignCenter, "Мышь   /   Пробел   /   Enter")
        previous_y = float(self.height())
        for burst in reversed(self.bursts):
            age = now - burst.born
            p.setPen(QColor(148, 255, 235, int(255 * (1-age/.9))))
            p.setFont(QFont("Segoe UI", 13, QFont.Weight.DemiBold))
            # Clamp texts inside the widget even for edge clicks.
            x = max(8, min(self.width()-184, burst.point.x()-88))
            y = max(34, burst.point.y()-55-(0 if self.reduced_motion else age*58))
            y = min(y, previous_y - 30)
            if y < 34:
                break
            previous_y = y
            p.drawText(QRectF(x, y, 176, 28), Qt.AlignmentFlag.AlignCenter, burst.text)
        p.end()
